CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float leaky_relu_op(float v, float slope) {
    return v >= 0.f ? v : v * slope;
}

// Processes 2 float4 (= 8 floats) per thread per iteration
__global__ void leaky_relu_vec_kernel(
    const float4* __restrict__ input,
    float4*       __restrict__ output,
    int64_t vec2_n,   // number of float4 pairs (each thread handles one pair = 8 floats)
    float negative_slope
) {
    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x  * blockDim.x;
    for (int64_t i = idx; i < vec2_n; i += stride) {
        float4 a = input[2*i];
        float4 b = input[2*i+1];
        a.x = leaky_relu_op(a.x, negative_slope);
        a.y = leaky_relu_op(a.y, negative_slope);
        a.z = leaky_relu_op(a.z, negative_slope);
        a.w = leaky_relu_op(a.w, negative_slope);
        b.x = leaky_relu_op(b.x, negative_slope);
        b.y = leaky_relu_op(b.y, negative_slope);
        b.z = leaky_relu_op(b.z, negative_slope);
        b.w = leaky_relu_op(b.w, negative_slope);
        output[2*i]   = a;
        output[2*i+1] = b;
    }
}

// Handles remaining float4 elements (0 or 1) after the paired loop
__global__ void leaky_relu_vec1_kernel(
    const float4* __restrict__ input,
    float4*       __restrict__ output,
    int64_t start_vec,
    int64_t vec_n,
    float negative_slope
) {
    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x  * blockDim.x;
    for (int64_t i = start_vec + idx; i < vec_n; i += stride) {
        float4 a = input[i];
        a.x = leaky_relu_op(a.x, negative_slope);
        a.y = leaky_relu_op(a.y, negative_slope);
        a.z = leaky_relu_op(a.z, negative_slope);
        a.w = leaky_relu_op(a.w, negative_slope);
        output[i] = a;
    }
}

// Handles scalar tail (< 4 elements)
__global__ void leaky_relu_tail_kernel(
    const float* __restrict__ input,
    float*       __restrict__ output,
    int64_t start,
    int64_t n,
    float negative_slope
) {
    int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x  * blockDim.x;
    for (int64_t i = start + idx; i < n; i += stride) {
        float v = input[i];
        output[i] = v >= 0.f ? v : v * negative_slope;
    }
}

torch::Tensor leaky_relu_cuda(torch::Tensor x, double negative_slope) {
    TORCH_CHECK(x.is_cuda(),  "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    auto output = torch::empty_like(x);
    int64_t n     = x.numel();
    float   slope = static_cast<float>(negative_slope);

    const float4* in4  = reinterpret_cast<const float4*>(x.data_ptr<float>());
    float4*       out4 = reinterpret_cast<float4*>(output.data_ptr<float>());

    int64_t vec_n  = n / 4;          // number of float4 elements
    int64_t vec2_n = vec_n / 2;      // number of float4 pairs
    int64_t tail   = n % 4;          // scalar tail

    const int block_size = 256;

    // Launch paired float4 kernel
    if (vec2_n > 0) {
        int64_t grid = (vec2_n + block_size - 1) / block_size;
        if (grid > 65535) grid = 65535;
        leaky_relu_vec_kernel<<<grid, block_size>>>(in4, out4, vec2_n, slope);
    }

    // Handle odd float4 (if vec_n is odd)
    int64_t start_vec = vec2_n * 2;
    if (start_vec < vec_n) {
        leaky_relu_vec1_kernel<<<1, block_size>>>(in4, out4, start_vec, vec_n, slope);
    }

    // Handle scalar tail
    if (tail > 0) {
        int64_t tail_start = vec_n * 4;
        leaky_relu_tail_kernel<<<1, block_size>>>(
            x.data_ptr<float>(), output.data_ptr<float>(),
            tail_start, n, slope);
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a LeakyReLU activation.
        """
    def __init__(self, negative_slope: float = 0.01):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the LeakyReLU module.

                Args:
                    negative_slope (float, optional): The negative slope of the activation function. Defaults to 0.01.
                """
        self.negative_slope = negative_slope
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies LeakyReLU activation to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of any shape.

                Returns:
                    torch.Tensor: Output tensor with LeakyReLU applied, same shape as input.
