        v0.x = leaky_relu_op(v0.x, negative_slope);
        v0.y = leaky_relu_op(v0.y, negative_slope);
        v0.z = leaky_relu_op(v0.z, negative_slope);
        v0.w = leaky_relu_op(v0.w, negative_slope);
        output[2*i] = v0;
        float4 v1 = __ldg(&input[2*i+1]);
        v1.x = leaky_relu_op(v1.x, negative_slope);
        v1.y = leaky_relu_op(v1.y, negative_slope);
        v1.z = leaky_relu_op(v1.z, negative_slope);
        v1.w = leaky_relu_op(v1.w, negative_slope);
        output[2*i+1] = v1;
    }
}

