static void _launch_leaky_relu(
    const float* in_ptr, float* out_ptr, int64_t numel,
    float slope, bool use_default, cudaStream_t stream
) {
    const int threads = 512;
    int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;

    bool aligned = (reinterpret_cast<uintptr_t>(in_ptr)  % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(out_ptr) % 16 == 0);

    if (aligned && numel >= 8) {
        int64_t vec2_n     = numel / 8;
        int64_t tail_start = vec2_n * 8;
        int64_t tail_n     = numel - tail_start;

        int64_t blocks = std::min<int64_t>((vec2_n + threads - 1) / threads, (int64_t)sm_count * 8);

        if (use_default) {
            leaky_relu_vec8_default_kernel<<<(int)blocks, threads, 0, stream>>>(
                reinterpret_cast<const float4*>(in_ptr),
                reinterpret_cast<float4*>(out_ptr),
                vec2_n
            );
        } else {
            leaky_relu_vec8_kernel<<<(int)blocks, threads, 0, stream>>>(
                reinterpret_cast<const float4*>(in_ptr),
                reinterpret_cast<float4*>(out_ptr),
                vec2_n,
                slope
            );
        }

        if (tail_n > 0) {
            int64_t tail_blocks = std::min<int64_t>((tail_n + threads - 1) / threads, (int64_t)sm_count * 8);
            if (use_default) {
                leaky_relu_scalar_default_kernel<<<(int)tail_blocks, threads, 0, stream>>>(
                    in_ptr + tail_start, out_ptr + tail_start, tail_n
                );
            } else {
                leaky_relu_scalar_kernel<<<(int)tail_blocks, threads, 0, stream>>>(
                    in_ptr + tail_start, out_ptr + tail_start, tail_n, slope
                );
            }
        }
    } else {
        int64_t blocks = std::min<int64_t>((numel + threads - 1) / threads, (int64_t)sm_count * 8);
        if (use_default) {
            leaky_relu_scalar_default_kernel<<<(int)blocks, threads, 0, stream>>>(
                in_ptr, out_ptr, numel
            );
        } else {
            leaky_relu_scalar_kernel<<<(int)blocks, threads, 0, stream>>>(
                in_ptr, out_ptr, numel, slope
            );
        }
    }
}

torch::Tensor leaky_relu_cuda(torch::Tensor x, double negative_slope) {
    TORCH_CHECK(x.is_cuda(), "leaky_relu_cuda: input must be on CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "leaky_relu_cuda: input must be float32");
    TORCH_CHECK(x.is_contiguous(), "leaky_relu_cuda: input must be contiguous");

    auto output = torch::empty_like(x);
    int64_t numel = x.numel();
    if (numel == 0) return output;

    float slope = static_cast<float>(negative_slope);
    const float* in_ptr  = x.data_ptr<float>();
    float*       out_ptr = output.data_ptr<float>();
    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    _launch_leaky_relu(in_ptr, out_ptr, numel, slope, false, stream);
    return output;
}

torch::Tensor leaky_relu_cuda_default(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "leaky_relu_cuda_default: input must be on CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "leaky_relu_cuda_default: input must be float32");
    TORCH_CHECK(x.is_contiguous(), "leaky_relu_cuda_default: input must be contiguous");

    auto output = torch::empty_like(x);
    int64_t numel = x.numel();
    if (numel == 0) return output;

    const float* in_ptr  = x.data_ptr<float>();
    float*       out_ptr = output.data_ptr<float>();
    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    _launch_leaky_relu(in_ptr, out_ptr, numel, 0.01f, true, stream);
    return output;
}
